// The ornaments of the «doorvase» door, traced from the customer's photo (see doorvase.ts for how).
//
// Reference frame: the drawing's outer engraved rectangle as rectified from the photo, REF_W × REF_H mm, x to the
// right and y down from its top-left corner. The drawing is mirror-symmetric about x = REF_W / 2: only the left half
// is stored.
// A stroke is a polyline x0, y0, x1, y1, … in mm (to 0.1 mm), of one of three kinds:
//   p  a stroke left of the axis; its mirror image is drawn too
//   s  a stroke that crosses the axis: its left half, ending on the axis (with closed, it starts on the axis too)
//   c  a stroke on the axis itself
// and of one of two weights, measured on the photo (the dark line's width across it, the median along the stroke, the
// mirror halves pooled; on the 590 mm drawing the photo's lines come out about 2.8 mm and 4.8 mm wide, two clear groups):
//   w: 'b'  bold: the outlines of the ornaments, engraved as several laser lines side by side
//   w: 'f'  fine: the inner details (veins, petal lines, the vase's flutes, curls), one laser line
// A bold stroke that turns fine for a stretch (an outline running on into an inner line) lists that stretch in f: pairs
// of vertex indices [from, to] into p, the segments between them fine (the mirror half and the mirrored half of an s
// stroke the same).

export const REF_W = 590
export const REF_H = 1563.5

/**
 * The structural lines in the reference frame, fitted to the photo: the panel lines' x (outer and inner line of each
 * double line) and the straight tops and bottoms' y; each arc as [its y on the axis, its radius] (the arcs sag
 * downwards, their centres above them on the axis). Top panel: straight top and sides, arc bottom; the band between
 * two arcs; lower panel: arc top, straight sides and bottom.
 */
export const REF = {
  xo: 31.89,
  xi: 42.51,
  topO: 34.51,
  topI: 45.75,
  botI: 1518.07,
  botO: 1529.34,
  topOutBot: [1127.05, 627.82] as const,
  topInBot: [1116.6, 617.38] as const,
  bandOutTop: [1158.81, 659.58] as const,
  bandInTop: [1169.26, 670.03] as const,
  bandOutBot: [1223.06, 853.43] as const,
  bandInBot: [1212.62, 842.98] as const,
  lowOutTop: [1255.45, 885.81] as const,
  lowInTop: [1265.9, 896.26] as const,
}

/** The weight of each structural line on the photo: the outer rectangle and each double line's outer line are fine, its inner line bold. */
export const FRAME_W = { rect: 'f', outer: 'f', inner: 'b' } as const

export interface Stroke { k: 'p' | 's' | 'c'; closed?: true; w: 'b' | 'f'; f?: number[]; p: number[] }

